import React from "react";
import { CheckCircle } from "lucide-react";

const CryptoTreeFlow = ({ currentStep }) => {
  const steps = [
    {
      id: 1,
      title: "Ephemeral Agreement",
      sub: "X25519",
      up: [],
      down: ["Generate ephemeral key", "Exchange public values"]
    },
    {
      id: 2,
      title: "Encapsulate Secret",
      sub: "Shared Secret",
      up: ["Create ciphertext"],
      down: ["Compute secret"]
    },
    {
      id: 3,
      title: "HKDF",
      sub: "SHA-256",
      up: [],
      down: ["Mix salt", "Expand AES key"]
    },
    {
      id: 4,
      title: "AES-GCM",
      sub: "Encryption",
      up: ["Generate tag"],
      down: ["Encrypt blocks"]
    },
    {
      id: 5,
      title: "Cloud Upload",
      sub: "Untrusted",
      up: [],
      down: ["Pack blob", "Push storage"]
    }
  ];

  return (
    <div className="relative bg-black/40 p-10 rounded-xl border border-scifi-border overflow-x-auto">
      
      {/* main pipeline */}
      <div className="flex justify-between items-center relative">
        <div className="absolute left-0 right-0 top-6 h-1 bg-gray-800"></div>

        <div
          className="absolute left-0 top-6 h-1 bg-neon-green transition-all duration-700"
          style={{
            width: `${((currentStep - 1) / (steps.length - 1)) * 100}%`
          }}
        />

        {steps.map((s, i) => {
          const active = currentStep >= s.id;

          return (
            <div key={s.id} className="relative w-40 flex flex-col items-center">

              {/* main node */}
              <div className={`z-10 w-12 h-12 rounded-full border-2 flex items-center justify-center
                ${active ? "border-neon-green text-neon-green" : "border-gray-700 text-gray-700"}`}>
                {active ? <CheckCircle size={18} /> : s.id}
              </div>

              <div className="mt-2 text-center">
                <div className={`text-xs font-bold ${active ? "text-white" : "text-gray-600"}`}>
                  {s.title}
                </div>
                <div className="text-[10px] text-gray-500">{s.sub}</div>
              </div>

              {/* UP BRANCHES */}
              {s.up.length > 0 && (
                <div className="absolute -top-16 flex flex-col items-center">
                  <div className={`h-10 w-[2px] ${active ? "bg-neon-green" : "bg-gray-700"}`}></div>
                  {s.up.map((b, idx) => (
                    <div key={idx} className={`text-[10px] font-mono ${active ? "text-neon-green" : "text-gray-600"}`}>
                      {b}
                    </div>
                  ))}
                </div>
              )}

              {/* DOWN BRANCHES */}
              {s.down.length > 0 && (
                <div className="absolute top-20 flex flex-col items-center">
                  <div className={`h-10 w-[2px] ${active ? "bg-neon-green" : "bg-gray-700"}`}></div>
                  {s.down.map((b, idx) => (
                    <div key={idx} className={`text-[10px] font-mono ${active ? "text-neon-green" : "text-gray-600"}`}>
                      {b}
                    </div>
                  ))}
                </div>
              )}

            </div>
          );
        })}
      </div>
    </div>
  );
};

export default CryptoTreeFlow;
